class Solution {
public:
    int findColoredRoot(vector<vector<int>>& edges, string colors) {
        int n = colors.size();
        vector<int> indegree(n, 0);
        vector<int> degree(n, 0);

        auto val = [](char c) -> int {
            if (c == 'R') return 0;
            if (c == 'B') return 1;
            return 2; // 'W'
        };

        for (auto& e : edges) {
            int u = e[0], v = e[1];
            int cu = val(colors[u]);
            int cv = val(colors[v]);
            degree[u]++;
            degree[v]++;
            if (cu == cv) return -1;
            // successor of cu in R->B->W->R is (cu + 1) % 3
            if ((cu + 1) % 3 == cv) {
                indegree[v]++;
            } else {
                indegree[u]++;
            }
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) return -1; // more than one root candidate
                root = i;
            }
        }

        if (root == -1 || degree[root] > 2) return -1;
        return root;
    }
};
